                <button type=\"submit\" class=\"btn btn-primary btn-appearance float-right btn-medium btn-xs-max-width\" @click=\"validateData\" :disabled=\"isDisabled\" :class=\"buttonSizeClass\" data-testing=\"unsub-nl-send\">\n                        <icon icon=\"paper-plane-o\" :loading=\"isDisabled\"></icon>\n                        <span>{{ $translate(\"Ceres::Template.newsletterUnsubscribeButtonLabel\") }}</span>\n                    </button>\n                </span>\n            </div>\n        </div>\n    </form>\n</template>\n\n<script>\nimport ApiService from \"../../services/ApiService\";\nimport ValidationService from \"../../services/ValidationService\";\nimport NotificationService from \"../../services/NotificationService\";\nimport UrlService from \"../../services/UrlService\";\n\nimport { isUndefined } from \"../../helper/utils\";\nimport { ButtonSizePropertyMixin } from \"../../mixins/buttonSizeProperty.mixin\";\n\nexport default {\n\n    mixins: [ButtonSizePropertyMixin],\n\n    data()\n    {\n        return {\n            email: \"\",\n            isDisabled: false,\n            honeypot: \"\"\n        };\n    },\n\n    methods: {\n        validateData()\n        {\n            this.isDisabled = true;\n\n            ValidationService.validate($(\"#newsletter-unsubscribe-input-form_\" + this._uid))\n                .done(() =>\n                {\n                    this.save();\n                })\n                .fail(invalidFields =>\n                {\n                    ValidationService.markInvalidFields(invalidFields, \"error\");\n\n                    this.isDisabled = false;\n                });\n        },\n\n        save()\n        {\n            const urlParams = UrlService.getUrlParams(document.location.search);\n\n            if (isUndefined( urlParams.folderId ))\n            {\n                urlParams.folderId = 0;\n            }\n\n            ApiService.del(\"/rest/io/customer/newsletter/\" + this.email, { \"emailFolder\": urlParams.folderId, \"honeypot\": this.honeypot })\n                .done(() =>\n                {\n                    NotificationService.success(\n                        this.$translate(\"Ceres::Template.newsletterOptOutSuccessMessage\")\n                    ).closeAfter(3000);\n                    this.resetInputs();\n                })\n                .fail(() =>\n                {\n                    NotificationService.error(\n                        this.$translate(\"Ceres::Template.newsletterOptOutErrorMessage\")\n                    ).closeAfter(5000);\n                })\n                .always(() =>\n                {\n                    this.isDisabled = false;\n                });\n        },\n\n        resetInputs()\n        {\n            this.email = \"\";\n        }\n    }\n}\n</script>\n","var render = function() {\n  var _vm = this\n  var _h = _vm.$createElement\n  var _c = _vm._self._c || _h\n  return _c(\n    \"form\",\n    {\n      attrs: {\n        id: \"newsletter-unsubscribe-input-form_\" + _vm._uid,\n        method: \"post\"\n      },\n      on: {\n        submit: function($event) {\n          $event.preventDefault()\n          return _vm.validateData($event)\n        }\n      }\n    },\n    [\n      _c(\"div\", { staticClass: \"row\" }, [\n        _c(\"div\", { staticClass: \"col-12\" }, [\n          _c(\n            \"div\",\n            {\n              staticClass: \"input-unit mt-3\",\n              attrs: { \"data-validate\": \"mail\" }\n            },\n            [\n              _c(\"label\", { attrs: { for: \"email-input-id\" } }, [\n                _vm._v(\n                  _vm._s(_vm.$translate(\"Ceres::Template.newsletterEmail\"))\n                )\n              ]),\n              _vm._v(\" \"),\n              _c(\"input\", {\n                directives: [\n                  {\n                    name: \"model\",\n                    rawName: \"v-model\",\n                    value: _vm.email,\n                    expr